"<script>\n"
"// ── Pure-JS SHA-256 + HMAC ───────────────────────────────────────────────────\n"
"// The device is served over plain HTTP on the LAN, where window.crypto.subtle\n"
"// is unavailable (it's restricted to secure contexts), so we hash in-page.\n"
"const _K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,\n"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,\n"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,\n"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,\n"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];\n"
"function _sha256(bytes){\n"
"  const rotr=(x,n)=>(x>>>n)|(x<<(32-n));\n"
"  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];\n"
"  const l=bytes.length,bitLen=l*8,withOne=l+1,k=(56-withOne%64+64)%64,total=withOne+k+8;\n"
"  const m=new Uint8Array(total); m.set(bytes); m[l]=0x80;\n"
"  const dv=new DataView(m.buffer);\n"
"  dv.setUint32(total-4,bitLen>>>0,false);\n"
"  dv.setUint32(total-8,Math.floor(bitLen/0x100000000),false);\n"
"  const w=new Uint32Array(64);\n"
"  for(let off=0;off<total;off+=64){\n"
"    for(let i=0;i<16;i++) w[i]=dv.getUint32(off+i*4,false);\n"
"    for(let i=16;i<64;i++){\n"
"      const s0=rotr(w[i-15],7)^rotr(w[i-15],18)^(w[i-15]>>>3);\n"
"      const s1=rotr(w[i-2],17)^rotr(w[i-2],19)^(w[i-2]>>>10);\n"
"      w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;\n"
"    }\n"
"    let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];\n"
"    for(let i=0;i<64;i++){\n"
"      const S1=rotr(e,6)^rotr(e,11)^rotr(e,25),ch=(e&f)^(~e&g);\n"
"      const t1=(h+S1+ch+_K[i]+w[i])>>>0;\n"
"      const S0=rotr(a,2)^rotr(a,13)^rotr(a,22),maj=(a&b)^(a&c)^(b&c);\n"
"      const t2=(S0+maj)>>>0;\n"
"      h=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;\n"
"    }\n"
"    H[0]=(H[0]+a)>>>0;H[1]=(H[1]+b)>>>0;H[2]=(H[2]+c)>>>0;H[3]=(H[3]+d)>>>0;\n"
"    H[4]=(H[4]+e)>>>0;H[5]=(H[5]+f)>>>0;H[6]=(H[6]+g)>>>0;H[7]=(H[7]+h)>>>0;\n"
"  }\n"
"  const out=new Uint8Array(32),odv=new DataView(out.buffer);\n"
"  for(let i=0;i<8;i++) odv.setUint32(i*4,H[i],false);\n"
"  return out;\n"
"}\n"
"function hmacSha256Hex(keyStr,msgStr){\n"
"  const enc=new TextEncoder();\n"
"  let key=enc.encode(keyStr); const msg=enc.encode(msgStr);\n"
"  if(key.length>64) key=_sha256(key);\n"
"  const k=new Uint8Array(64); k.set(key);\n"
"  const ip=new Uint8Array(64),op=new Uint8Array(64);\n"
"  for(let i=0;i<64;i++){ ip[i]=k[i]^0x36; op[i]=k[i]^0x5c; }\n"
"  const i1=new Uint8Array(64+msg.length); i1.set(ip); i1.set(msg,64);\n"
"  const inner=_sha256(i1);\n"
"  const o1=new Uint8Array(96); o1.set(op); o1.set(inner,64);\n"
"  return Array.from(_sha256(o1),x=>x.toString(16).padStart(2,'0')).join('');\n"
"}\n"
"\n"
"// ── Login flow ────────────────────────────────────────────────────────────────\n"
"let MULTIUSER = false;\n"
"\n"
"(async function init(){\n"
"  try {\n"
"    const j = await (await fetch('/api/authinfo', {cache:'no-store'})).json();\n"
"    MULTIUSER = !!j.multiuser;\n"
"  } catch(e) { MULTIUSER = false; }\n"
"  if (MULTIUSER) {\n"
"    const u = document.getElementById('user');\n"
"    u.classList.remove('hidden');\n"
"    document.getElementById('sub').textContent = 'SIGN IN';\n"
"    let last = '';\n"
"    try { last = localStorage.getItem('nethid.lastuser') || ''; } catch(e) {}\n"
"    if (last) {                 // remembered name → prefill and jump to the password\n"
"      u.value = last;\n"
"      document.getElementById('pw').focus();\n"
"    } else {\n"
"      u.focus();\n"
"    }\n"
"  } else {\n"
"    document.getElementById('pw').focus();\n"
"  }\n"
"})();\n"
"\n"
"function showErr(msg, cls){\n"
"  const err = document.getElementById('err');\n"
"  err.textContent = msg;\n"
"  err.className = 'error visible' + (cls ? ' ' + cls : '');\n"
"}\n"
"\n"
"async function login(){\n"
"  const go = document.getElementById('go');\n"
"  const user = MULTIUSER ? document.getElementById('user').value.trim() : '';\n"
"  const pw = document.getElementById('pw').value;\n"
"  document.getElementById('err').className = 'error';\n"
"  if (MULTIUSER && !user) { showErr('Enter a username.'); return; }\n"
"  go.disabled = true;\n"
"  try {\n"
"    // 1) fetch a one-time nonce\n"
"    const cr = await fetch('/api/challenge', {cache:'no-store'});\n"
"    const cj = await cr.json();\n"
"    if (!cj.nonce) {\n"
"      showErr(cj.error === 'busy' ? 'Server busy — try again.' : 'Cannot start login.');\n"
"      go.disabled = false; return;\n"
"    }\n"
"    // 2) response = HMAC-SHA256(password, nonce)\n"
"    const response = hmacSha256Hex(pw, cj.nonce);\n"
"    // 3) authenticate (password never leaves this page)\n"
"    const r = await fetch('/api/auth', {\n"
"      method: 'POST', headers: {'Content-Type': 'application/json'},\n"
"      body: JSON.stringify({user: user, nonce: cj.nonce, response: response})\n"
"    });\n"
"    const j = await r.json();\n"
"    if (j.ok) {\n"
"      if (MULTIUSER) { try { localStorage.setItem('nethid.lastuser', user); } catch(e) {} }\n"
"      window.location.replace('/');\n"
"      return;\n"
"    }\n"
"    if (j.error === 'locked') {\n"
"      showErr('Too many attempts. Locked for ' + j.retry_after + 's.', 'locked');\n"
"    } else {\n"
"      showErr(MULTIUSER ? 'Wrong username or password.' : 'Incorrect password.');\n"
"      document.getElementById('pw').value = '';\n"
"      document.getElementById(MULTIUSER ? 'user' : 'pw').focus();\n"
"    }\n"
"  } catch(e) {\n"
"    showErr('Connection error.');\n"
"  }\n"
"  go.disabled = false;\n"
"}\n"
"</script>\n"
"</body>\n"
"</html>\n";

