"  @keyframes p{0%,100%{opacity:1}50%{opacity:.4}}\n"
"</style>\n"
"</head>\n"
"<body>\n"
"\n"
"<h1>Learn a remote</h1>\n"
"<p class=\"sub\">Capture IR or 433 MHz codes from your own remotes, replay them, and save them in this browser.</p>\n"
"\n"
"<div class=\"hint\">\n"
"  Point the source remote at the receiver, click <b>Learn</b>, then press a button. IR uses the\n"
"  TSOP receiver (GPIO18); RF uses the 433 MHz receiver (GPIO19). RF is noisier — it may take a couple\n"
"  of presses. Captured codes replay through this NetHID's IR LED / 433 transmitter.\n"
"</div>\n"
"\n"
"<div class=\"row\">\n"
"  <button class=\"primary\" id=\"learnIr\" onclick=\"learn('ir')\">Learn IR</button>\n"
"  <button class=\"primary\" id=\"learnRf\" onclick=\"learn('rf')\">Learn RF</button>\n"
"  <button class=\"ghost\" id=\"cancelBtn\" onclick=\"cancel()\" disabled>Cancel</button>\n"
"</div>\n"
"<div class=\"status\" id=\"status\"></div>\n"
"\n"
"<div id=\"captureCard\"></div>\n"
"\n"
"<h2>Saved</h2>\n"
"<div id=\"saved\"></div>\n"
"\n"
"<script>\n"
"const $ = id => document.getElementById(id);\n"
"let polling = null, pollKind = null, lastCapture = null;\n"
"\n"
"function setStatus(msg, cls){ const e=$('status'); e.textContent=msg||''; e.className='status'+(cls?' '+cls:''); }\n"
"function busy(on){ $('learnIr').disabled=on; $('learnRf').disabled=on; $('cancelBtn').disabled=!on; }\n"
"const sleep = ms => new Promise(r=>setTimeout(r,ms));\n"
"\n"
"async function jpost(url, body){\n"
"  return fetch(url, {method:'POST', credentials:'same-origin',\n"
"    headers: body?{'Content-Type':'application/json'}:undefined,\n"
"    body: body?JSON.stringify(body):undefined});\n"
"}\n"
"\n"
"async function learn(kind){\n"
"  cancel();                                  // clear any prior poll\n"
"  pollKind = kind;\n"
"  busy(true);\n"
"  setStatus('Arming '+kind.toUpperCase()+'…', 'wait');\n"
"  try {\n"
"    const r = await jpost('/api/'+kind+'/learn');\n"
"    if (r.status === 401){ setStatus('Session expired — reload the page.', 'err'); busy(false); return; }\n"
"    if (!r.ok){ setStatus('Could not arm ('+r.status+'). Is ENABLE_REMOTES on?', 'err'); busy(false); return; }\n"
"  } catch(e){ setStatus('Network error arming capture.', 'err'); busy(false); return; }\n"
"\n"
"  setStatus('Point your '+kind.toUpperCase()+' remote at the receiver and press a button…', 'wait');\n"
"  const deadline = Date.now() + 16000;\n"
"  polling = true;\n"
"  while (polling && Date.now() < deadline){\n"
"    await sleep(350);\n"
"    if (!polling) return;                    // cancelled\n"
"    let j;\n"
"    try { j = await (await fetch('/api/'+kind+'/captured', {credentials:'same-origin', cache:'no-store'})).json(); }\n"
"    catch(e){ continue; }\n"
"    if (j.ready){ polling=false; busy(false); showCapture(kind, j); return; }\n"
"    if (j.armed === false){ break; }          // firmware gave up\n"
"  }\n"
"  if (polling){ polling=false; }\n"
"  busy(false);\n"
"  setStatus('No signal captured — try again (hold the button briefly).', 'err');\n"
"}\n"
"\n"
"function cancel(){ if(polling){ polling=false; busy(false); setStatus('Cancelled.'); } }\n"
"\n"
"function captureLabel(c){\n"
"  if (c.proto === 'nec') return 'IR · NEC · code '+c.code;\n"
"  if (c.kind === 'rf')   return 'RF · raw · '+c.count+' edges';\n"
"  return 'IR · raw · '+c.count+' edges';\n"
"}\n"
"\n"
"function showCapture(kind, j){\n"
"  lastCapture = { kind, proto:j.proto, code:j.code, carrier:j.carrier||38000, timings:j.timings||[], count:j.count };\n"
"  setStatus('Captured ✓', 'ok');\n"
"  $('captureCard').innerHTML = `\n"
"    <div class=\"card\">\n"
"      <div><b>${captureLabel(lastCapture)}</b></div>\n"
"      <div class=\"meta\">${kind.toUpperCase()} · ${lastCapture.timings.length} timings${lastCapture.proto==='nec'?` · code <code>${lastCapture.code}</code>`:''}</div>\n"
"      <div class=\"row\" style=\"margin-top:10px\">\n"
"        <button class=\"primary\" onclick=\"replay(window._cap)\">Replay</button>\n"
"        <input id=\"saveName\" placeholder=\"name (e.g. TV power)\" style=\"flex:1;min-width:120px\">\n"
"        <button onclick=\"saveCapture()\">Save</button>\n"
"      </div>\n"
"    </div>`;\n"
"  window._cap = lastCapture;\n"
"}\n"
"\n"
"async function replay(item){\n"
"  try {\n"
"    let r;\n"
"    if (item.kind === 'rf') r = await jpost('/api/rf', {timings:item.timings, repeat:8});\n"
"    else                    r = await jpost('/api/ir', {proto:'raw', carrier:item.carrier||38000, timings:item.timings});\n"
"    if (r.status===401) return setStatus('Session expired — reload.', 'err');\n"
"    setStatus(r.ok ? 'Replayed ✓' : 'Replay error '+r.status, r.ok?'ok':'err');\n"
"  } catch(e){ setStatus('Replay failed.', 'err'); }\n"
"}\n"
"\n"
"// ── saved (localStorage) ────────────────────────────────────────────────────\n"
"const KEY = 'nethid.learned';\n"
"const load = () => { try { return JSON.parse(localStorage.getItem(KEY)||'[]'); } catch(e){ return []; } };\n"
"const store = a => localStorage.setItem(KEY, JSON.stringify(a));\n"
"\n"
"function saveCapture(){\n"
"  if (!lastCapture) return;\n"
"  const name = ($('saveName').value || '').trim() || (lastCapture.kind.toUpperCase()+' '+Date.now().toString(36));\n"
"  const a = load();\n"
"  a.push({ id:'l'+Date.now().toString(36), name, kind:lastCapture.kind, proto:lastCapture.proto,\n"
"           code:lastCapture.code, carrier:lastCapture.carrier, timings:lastCapture.timings });\n"
"  store(a); renderSaved(); setStatus('Saved “'+name+'”.', 'ok');\n"
"}\n"
"\n"
"function delSaved(id){ store(load().filter(x=>x.id!==id)); renderSaved(); }\n"
"function replaySaved(id){ const it = load().find(x=>x.id===id); if (it) replay(it); }\n"
"\n"
"function renderSaved(){\n"
"  const a = load();\n"
"  if (!a.length){ $('saved').innerHTML = '<p class=\"meta\">Nothing saved yet.</p>'; return; }\n"
"  let h = '<table><tr><th>Name</th><th>Type</th><th>Detail</th><th>Actions</th></tr>';\n"
"  for (const it of a){\n"
"    const detail = it.proto==='nec' ? ('code '+it.code) : (it.timings.length+' edges');\n"
"    h += `<tr><td>${it.name}</td><td>${it.kind.toUpperCase()}</td><td class=\"meta\">${it.proto} · ${detail}</td>\n"
"      <td class=\"row\">\n"
"        <button class=\"primary\" onclick=\"replaySaved('${it.id}')\">Replay</button>\n"
"        <button onclick=\"delSaved('${it.id}')\">✕</button>\n"
"      </td></tr>`;\n"
"  }\n"
"  h += '</table>';\n"
"  $('saved').innerHTML = h;\n"
"}\n"
"\n"
"renderSaved();\n"
"</script>\n"
"\n"
"</body>\n"
"</html>\n";

